    "CREATE OR REPLACE FUNCTION medexa_attempt_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE duration interval;\nBEGIN\n IF TG_OP='INSERT' THEN\n  IF NEW.snapshot_ready OR NEW.status<>'in_progress' OR NEW.current_position<>0 OR NEW.version<>1 THEN RAISE EXCEPTION 'Invalid new attempt'; END IF;\n  duration=NEW.deadline_at-NEW.started_at; NEW.started_at=clock_timestamp(); IF NEW.mode='exam' THEN NEW.deadline_at=NEW.started_at+duration; END IF; RETURN NEW;\n END IF;\n IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Attempt history cannot be deleted'; END IF;\n IF to_jsonb(NEW)=to_jsonb(OLD) THEN RETURN NEW; END IF;\n IF NOT OLD.snapshot_ready THEN\n  IF NOT NEW.snapshot_ready OR (to_jsonb(NEW)-'snapshot_ready')<>(to_jsonb(OLD)-'snapshot_ready') THEN RAISE EXCEPTION 'Snapshot must be sealed atomically'; END IF;\n  IF (SELECT count(*) FROM attempt_items WHERE attempt_id=NEW.id)<>NEW.total OR\n     (SELECT min(position) FROM attempt_items WHERE attempt_id=NEW.id)<>0 OR\n     (SELECT max(position) FROM attempt_items WHERE attempt_id=NEW.id)<>NEW.total-1 THEN RAISE EXCEPTION 'Incomplete question snapshot'; END IF;\n  IF EXISTS(SELECT 1 FROM attempt_items i JOIN question_revisions r ON r.id=i.revision_id JOIN questions q ON q.id=i.question_id\n    WHERE i.attempt_id=NEW.id AND (r.status<>'published' OR r.kind<>'single_choice' OR q.current_revision_id IS DISTINCT FROM r.id OR q.archived_at IS NOT NULL\n    OR (SELECT count(*) FROM attempt_item_options o WHERE o.item_id=i.id) NOT BETWEEN 2 AND 8\n    OR (SELECT count(*) FROM attempt_item_options o WHERE o.item_id=i.id)<>(SELECT count(*) FROM question_options o WHERE o.revision_id=i.revision_id)\n    OR (SELECT count(*) FROM question_options o WHERE o.revision_id=i.revision_id AND o.is_correct)<>1\n    OR NOT EXISTS(SELECT 1 FROM topic_questions tq JOIN topics t ON t.id=tq.topic_id JOIN disciplines d ON d.id=t.discipline_id\n       LEFT JOIN categories c ON c.id=t.category_id LEFT JOIN access_policies p ON p.id=t.access_policy_id\n       WHERE tq.question_id=i.question_id AND d.id=NEW.discipline_id AND (NEW.topic_id IS NULL OR t.id=NEW.topic_id)\n       AND d.status='published' AND t.status='published' AND (t.category_id IS NULL OR c.status='published')\n       AND (t.access_policy_id IS NULL OR (p.status='published' AND p.requirement='authenticated')))))\n    THEN RAISE EXCEPTION 'Unavailable or unsupported question snapshot'; END IF;\n  IF EXISTS(SELECT 1 FROM attempt_items i WHERE i.attempt_id=NEW.id AND\n     ((SELECT min(position) FROM attempt_item_options WHERE item_id=i.id)<>0 OR\n      (SELECT max(position) FROM attempt_item_options WHERE item_id=i.id)<>(SELECT count(*)-1 FROM attempt_item_options WHERE item_id=i.id))) THEN RAISE EXCEPTION 'Invalid option order'; END IF;\n  RETURN NEW;\n END IF;\n IF OLD.status<>'in_progress' THEN RAISE EXCEPTION 'Terminal attempt is immutable'; END IF;\n IF (to_jsonb(NEW)-ARRAY['status','current_position','version','finalized_at','finish_reason','correct','wrong','skipped','answered','percent','duration_seconds']) <>\n    (to_jsonb(OLD)-ARRAY['status','current_position','version','finalized_at','finish_reason','correct','wrong','skipped','answered','percent','duration_seconds'])\n    OR NEW.version<>OLD.version+1 OR (NEW.mode='learning' AND NEW.current_position NOT BETWEEN OLD.current_position AND OLD.current_position+1)\n    THEN RAISE EXCEPTION 'Invalid attempt transition/version'; END IF;\n IF NEW.mode='learning' AND NEW.current_position<>OLD.current_position AND NOT EXISTS(SELECT 1 FROM attempt_items i JOIN attempt_responses r ON r.item_id=i.id WHERE i.attempt_id=OLD.id AND i.position=OLD.current_position)\n THEN RAISE EXCEPTION 'Cannot advance unanswered item'; END IF;\n RETURN NEW; END; $$",
    "CREATE OR REPLACE FUNCTION medexa_attempt_response_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE a attempts%ROWTYPE; ip int; correct bool;\nBEGIN\n IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Committed response is immutable'; END IF;\n SELECT * INTO a FROM attempts WHERE id=NEW.attempt_id FOR UPDATE;\n SELECT position INTO ip FROM attempt_items WHERE id=NEW.item_id AND attempt_id=NEW.attempt_id AND revision_id=NEW.revision_id;\n IF NOT FOUND OR NOT a.snapshot_ready OR a.status<>'in_progress' OR (a.mode='learning' AND ip<a.current_position) THEN RAISE EXCEPTION 'Invalid response state'; END IF;\n IF NEW.state='committed' THEN\n  SELECT q.is_correct INTO correct FROM attempt_item_options o JOIN question_options q ON q.id=o.option_id WHERE o.item_id=NEW.item_id AND o.option_id=NEW.selected_option_id AND o.revision_id=NEW.revision_id;\n  IF NOT FOUND OR (a.mode='learning' AND ip<>a.current_position) OR NEW.is_correct IS DISTINCT FROM correct THEN RAISE EXCEPTION 'Invalid selection/score'; END IF;\n END IF;\n IF a.mode='exam' AND NEW.state='committed' AND NOT EXISTS(SELECT 1 FROM exam_answers e WHERE e.item_id=NEW.item_id AND e.selected_option_id=NEW.selected_option_id) THEN RAISE EXCEPTION 'Exam answer mismatch'; END IF; NEW.attempt_version=a.version+1; NEW.committed_at=clock_timestamp(); RETURN NEW; END; $$",
    "CREATE OR REPLACE FUNCTION medexa_attempt_consistency() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE a attempts%ROWTYPE; aid uuid; n int; c int; w int; s int;\nBEGIN\n IF TG_TABLE_NAME='attempts' THEN aid=NEW.id; ELSE aid=NEW.attempt_id; END IF;\n SELECT * INTO a FROM attempts WHERE id=aid;\n IF NOT FOUND THEN RETURN NULL; END IF;\n IF NOT a.snapshot_ready THEN RAISE EXCEPTION 'Unsealed attempt cannot commit'; END IF;\n IF TG_TABLE_NAME IN ('attempt_responses','exam_answers') THEN\n  IF a.version<NEW.attempt_version THEN RAISE EXCEPTION 'Response requires a versioned command'; END IF;\n  IF a.mode='exam' AND TG_TABLE_NAME='attempt_responses' AND a.status<>'completed' THEN RAISE EXCEPTION 'Exam responses require finalization'; END IF;\n  RETURN NULL;\n END IF;\n IF a.mode='learning' AND a.status='in_progress' AND EXISTS(SELECT 1 FROM attempt_items i LEFT JOIN attempt_responses r ON r.item_id=i.id WHERE i.attempt_id=aid AND\n ((i.position<a.current_position AND r.item_id IS NULL) OR (i.position>a.current_position AND r.item_id IS NOT NULL) OR (i.position=a.current_position AND r.state='skipped')))\n THEN RAISE EXCEPTION 'Invalid learning cursor'; END IF;\n IF a.mode='exam' AND a.status='completed' AND EXISTS(SELECT 1 FROM attempt_items i LEFT JOIN exam_answers e ON e.item_id=i.id LEFT JOIN attempt_responses r ON r.item_id=i.id WHERE i.attempt_id=aid AND r.selected_option_id IS DISTINCT FROM e.selected_option_id) THEN RAISE EXCEPTION 'Exam result must match saved answers'; END IF;\n IF a.mode='exam' AND a.status='completed' AND (a.finalized_at>a.deadline_at OR (a.finish_reason='timeout' AND a.finalized_at<>a.deadline_at)) THEN RAISE EXCEPTION 'Invalid exam final time'; END IF;\n IF a.status='completed' THEN\n SELECT count(*),count(*) FILTER(WHERE state='committed' AND is_correct),count(*) FILTER(WHERE state='committed' AND NOT is_correct),count(*) FILTER(WHERE state='skipped') INTO n,c,w,s FROM attempt_responses WHERE attempt_id=aid;\n IF n<>a.total OR a.correct<>c OR a.wrong<>w OR a.skipped<>s OR a.answered<>c+w OR a.percent<>round(c*100.0/a.total) OR\n a.duration_seconds<>floor(extract(epoch FROM a.finalized_at-a.started_at)) THEN RAISE EXCEPTION 'Invalid frozen result'; END IF;\n END IF;\n RETURN NULL; END; $$",
    "CREATE FUNCTION medexa_exam_answer_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE a attempts%ROWTYPE;\nBEGIN\n IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Exam answer cannot be deleted'; END IF;\n SELECT * INTO a FROM attempts WHERE id=NEW.attempt_id FOR UPDATE;\n IF NOT FOUND OR a.mode<>'exam' OR NOT a.snapshot_ready OR a.status<>'in_progress' OR clock_timestamp()>=a.deadline_at THEN RAISE EXCEPTION 'Exam is closed'; END IF;\n IF TG_OP='UPDATE' AND (NEW.item_id,NEW.attempt_id,NEW.revision_id) IS DISTINCT FROM (OLD.item_id,OLD.attempt_id,OLD.revision_id) THEN RAISE EXCEPTION 'Exam answer identity is immutable'; END IF;\n NEW.saved_at=clock_timestamp(); NEW.attempt_version=a.version+1; RETURN NEW;\nEND; $$",
