def upgrade():
    for statement in DDL:
        op.execute(sa.text(statement))


def downgrade():
    if op.get_bind().scalar(sa.text("SELECT EXISTS(SELECT 1 FROM attempts WHERE mode='exam')")):
        raise RuntimeError("0009 downgrade blocked: exam history exists; use forward fix")
    op.drop_table("exam_answers")
    op.execute("DROP FUNCTION medexa_exam_answer_guard()")
    for statement in OLD_FUNCTIONS:
        op.execute(sa.text(statement.replace("CREATE FUNCTION", "CREATE OR REPLACE FUNCTION", 1)))
    op.drop_index("ix_attempts_exam_deadline", table_name="attempts")
    op.drop_constraint("ck_attempts_deadline", "attempts")
    op.drop_column("attempts", "deadline_at")
    op.drop_constraint("ck_attempts_mode_policy", "attempts")
    op.create_check_constraint(
        op.f("ck_attempts_mode_policy"), "attempts", "mode='learning' AND policy_version=1"
    )
